  repository(owner: $owner, name: $repo) {
    ref(qualifiedName: "refs/heads/suggestion-pr/56/bb3b8acd-0bdf-4464-b341-8802383b6935") {
      name prefix
      associatedPullRequests(first: 10) { totalCount nodes { number state headRefName baseRefName } }
    }
    pullRequest(number: 58) { number state headRefName baseRefName headRepository { nameWithOwner } }
  }
}
